<?php
require_once __DIR__.'/config.php';$id=valid_id($_GET['id']??0);$stmt=$pdo->prepare("SELECT g.*,s.name subject_name,u.name creator FROM study_groups g LEFT JOIN subjects s ON s.id=g.subject_id JOIN users u ON u.id=g.creator_id WHERE g.id=?");$stmt->execute([$id]);$g=$stmt->fetch();if(!$g){http_response_code(404);$pageTitle='Group not found';require __DIR__.'/includes/header.php';echo '<div class="container page-content"><div class="empty-state"><h2>Group not found</h2><a class="btn btn-primary" href="groups.php">Back to groups</a></div></div>';require __DIR__.'/includes/footer.php';exit;}
$isMember=false;if(current_user()){$m=$pdo->prepare('SELECT 1 FROM group_members WHERE group_id=? AND user_id=?');$m->execute([$id,current_user()['id']]);$isMember=(bool)$m->fetchColumn();}
if(is_post()){require_login();verify_csrf();if(!$isMember){set_flash('error','Join this group before scheduling a session.');redirect('group.php?id='.$id);}$title=posted_string('title',180);$location=posted_string('location_or_link',500);$start=strtotime((string)($_POST['start_time']??''));$end=strtotime((string)($_POST['end_time']??''));if(mb_strlen($title)<4||!$start||!$end||$end<=$start||$start<time())set_flash('error','Enter a valid session title and future start/end times.');else{$pdo->prepare('INSERT INTO study_sessions(group_id,title,location_or_link,start_time,end_time,created_by) VALUES(?,?,?,?,?,?)')->execute([$id,$title,$location,date('Y-m-d H:i:s',$start),date('Y-m-d H:i:s',$end),current_user()['id']]);set_flash('success','Study session scheduled.');}redirect('group.php?id='.$id);}
$members=$pdo->prepare('SELECT u.name,u.email FROM group_members gm JOIN users u ON u.id=gm.user_id WHERE gm.group_id=? ORDER BY gm.joined_at');$members->execute([$id]);$members=$members->fetchAll();$sessions=$pdo->prepare('SELECT ss.*,u.name creator FROM study_sessions ss JOIN users u ON u.id=ss.created_by WHERE ss.group_id=? ORDER BY ss.start_time');$sessions->execute([$id]);$sessions=$sessions->fetchAll();$pageTitle=$g['name'];require __DIR__.'/includes/header.php';?>
<section class="page-hero"><div class="container"><a href="groups.php">← All study groups</a><div class="mt-2"><span class="eyebrow"><?= e($g['subject_name']??'General') ?> · Study group</span><h1><?= e($g['name']) ?></h1><p>Created by <?= e($g['creator']) ?></p></div></div></section><div class="page-content"><div class="container detail-layout"><div class="content-stack"><section class="panel"><h2>About this group</h2><p><?= e($g['description']) ?></p><p class="small-muted"><?= count($members) ?> members</p><?php if(current_user()): ?><form method="post" action="groups.php"><?= csrf_field() ?><input type="hidden" name="group_id" value="<?= $id ?>"><?php if($isMember): ?><input type="hidden" name="action" value="leave"><button class="btn btn-outline">Leave group</button><?php else: ?><input type="hidden" name="action" value="join"><button class="btn btn-primary">Join group</button><?php endif; ?></form><?php else: ?><a class="btn btn-primary" href="login.php">Log in to join</a><?php endif; ?></section>
<section class="panel"><div class="section-heading"><div><h2>Upcoming study sessions</h2><p>Plan a time to learn together.</p></div></div><?php if($sessions): foreach($sessions as $s): ?><article class="card mb-2"><h3><?= e($s['title']) ?></h3><p><strong><?= e(date('D, M j · g:i A',strtotime($s['start_time']))) ?></strong> – <?= e(date('g:i A',strtotime($s['end_time']))) ?></p><?php if($s['location_or_link']): ?><p><?= e($s['location_or_link']) ?></p><?php endif; ?><span class="small-muted">Scheduled by <?= e($s['creator']) ?></span></article><?php endforeach; else: ?><p>No sessions scheduled yet.</p><?php endif; ?></section>
<?php if($isMember): ?><section class="panel"><h2>Schedule a session</h2><form method="post"><?= csrf_field() ?><div class="form-group"><label for="title">Session title</label><input id="title" name="title" required placeholder="e.g. Revision: linked lists"></div><div class="form-group"><label for="location_or_link">Location or meeting link</label><input id="location_or_link" name="location_or_link" maxlength="500" placeholder="Library, room number, or online meeting link"></div><div class="grid-2"><div class="form-group"><label for="start_time">Starts</label><input id="start_time" name="start_time" type="datetime-local" required></div><div class="form-group"><label for="end_time">Ends</label><input id="end_time" name="end_time" type="datetime-local" required></div></div><button class="btn btn-primary">Schedule session</button></form></section><?php endif; ?></div>
<aside class="panel"><h3>Group members</h3><?php foreach($members as $m): ?><p><strong><?= e($m['name']) ?></strong></p><?php endforeach; ?></aside></div></div><?php require __DIR__.'/includes/footer.php';?>
